sp_widget.client_script:
api.controller=function() {
    // Ensure that the data exists and contains onboarding records
    if (data.onboardingStatusList && data.onboardingStatusList.length > 0) {
        api.controller.setData('onboardingStatusList', data.onboardingStatusList);
    } else {
        api.controller.setData('noOnboardingStatusMessage', "No onboarding requests at the moment.");
    }
}();

sp_widget.css:
/* Container for the widget */
.onboarding-status-widget {
    font-family: 'Arial', sans-serif;
    background-color: #f9f9f9;
    padding: 15px;
    border-radius: 5px;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}

/* Each item in the onboarding status list */
.onboarding-status-item {
    background-color: #fff;
    border: 1px solid #ddd;
    border-radius: 5px;
    margin-bottom: 10px;
    padding: 10px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

/* Hover effect on each item */
.onboarding-status-item:hover {
    transform: scale(1.02);
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

/* Title for the request */
.onboarding-status-item strong {
    color: #333;
}

/* No data message styling */
.onboarding-status-widget p {
    color: #888;
    font-size: 14px;
}

sp_widget.script:
(function() {
    var onboardingStatusList = [];

    // Use GlideRecord to query the Onboarding Request table (adjust the table name if necessary)
    var onboardingGr = new GlideRecord('x_1583423_hr_hroo_employee_onboarding');  // Replace with your Onboarding Request table name
    onboardingGr.addQuery('state', '!=', 'Complete'); // Fetch records that are not complete
    onboardingGr.addQuery('requested_for', gs.getUserID()); // Only the logged-in user
    onboardingGr.query();

    // Store the relevant details in an array
    while (onboardingGr.next()) {
        onboardingStatusList.push({
            request_number: onboardingGr.number.toString(),  // Converting sys_id to string
            status: onboardingGr.state.getDisplayValue(),  // Get the state display value
            requested_for: onboardingGr.requested_for.getDisplayValue(),
            date_requested: onboardingGr.sys_created_on.getDisplayValue()
        });
    }

    // Return the data to the client script
    data.onboardingStatusList = onboardingStatusList;
})();
